@@ -0,0 +1,46 @@
+import path from "node:path";
+import { mkdtemp, writeFile } from "node:fs/promises";
+import { tmpdir } from "node:os";
+import { realpath } from "node:fs/promises";
+
+// Minimal unit coverage for traversal prevention helper behavior.
+// (This is intentionally small and does not spin up the full server.)
+
+function resolvePathWithinBase(baseDir: string, urlPathname: string): string | null {
+	let pathname: string;
+	try {
+		pathname = decodeURIComponent(urlPathname);
+	} catch {
+		return null;
+	}
+	if (pathname.includes("\0")) return null;
+	pathname = pathname.replace(/^\/+/, "");
+	const candidatePath = path.resolve(baseDir, pathname);
+	const relative = path.relative(baseDir, candidatePath);
+	if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative))) return candidatePath;
+	return null;
+}
+
+describe("pages dev path traversal prevention", () => {
+	it("rejects .. traversal outside the base directory", async () => {
+		const base = await mkdtemp(path.join(tmpdir(), "wrangler-pages-dev-"));
+		const baseReal = await realpath(base);
+		await writeFile(path.join(baseReal, "ok.txt"), "ok");
+		expect(resolvePathWithinBase(baseReal, "/../secret.txt")).toBeNull();
+		expect(resolvePathWithinBase(baseReal, "/%2e%2e/secret.txt")).toBeNull();
+	});
+
+	it("allows normal paths within base directory", async () => {
+		const base = await mkdtemp(path.join(tmpdir(), "wrangler-pages-dev-"));
+		const baseReal = await realpath(base);
+		expect(resolvePathWithinBase(baseReal, "/assets/app.js")).toBe(
+			path.resolve(baseReal, "assets/app.js")
+		);
+	});
+});

