+'use strict'
+
+var execFile = require('child_process').execFile
+
+function normalizePids (pids) {
+  if (pids === null || pids === undefined) return null
+
+  if (!Array.isArray(pids)) pids = [pids]
+
+  var out = []
+  for (var i = 0; i < pids.length; i++) {
+    var p = String(pids[i]).trim()
+    if (!/^\d+$/.test(p)) return null
+    out.push(p)
+  }
+
+  return out.join(',')
+}
+
+module.exports = function ps (pid, callback) {
+  var pidList = normalizePids(pid)
+  if (!pidList) {
+    return process.nextTick(function () {
+      callback(new Error('Invalid pid'))
+    })
+  }
+
+  execFile('ps', ['-o', 'pcpu=,rss=', '-p', pidList], function (err, stdout) {
+    if (err) return callback(err)
+
+    stdout = stdout.toString().trim().split(/\s+/)
+    callback(null, {
+      cpu: parseFloat(stdout[0]),
+      memory: parseInt(stdout[1], 10) * 1024
+    })
+  })
+}

